  c += vec3(1., .74, .42) * 1.6 * smoothstep(.994, .999, dot(r, normalize(vec3(.30, .78, .40))));
  c += vec3(1., .72, .40) * 1.3 * smoothstep(.995, .999, dot(r, normalize(vec3(-.80, .42, .32))));
